import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:integration_test/integration_test.dart';
import 'package:flutter_casino_demo/main.dart' as app;

void main() {
  IntegrationTestWidgetsFlutterBinding.ensureInitialized();

  group('🎰 Flutter Casino Demo - Complete Automation Validation', () {
    
    testWidgets('🔍 Critical Keys Validation Workflow', (WidgetTester tester) async {
      // Initialize casino app
      app.main();
      await tester.pumpAndSettle(const Duration(seconds: 2));
      
      print('🚀 Starting comprehensive key validation workflow...');
      
      // Phase 1: Validate core navigation keys
      await _validateNavigationKeys(tester);
      
      // Phase 2: Validate slots game module
      await _validateSlotsModule(tester);
      
      // Phase 3: Validate roulette game module  
      await _validateRouletteModule(tester);
      
      // Phase 4: Validate blackjack game module
      await _validateBlackjackModule(tester);
      
      // Phase 5: Validate demo automation system
      await _validateDemoAutomation(tester);
      
      print('✅ All casino automation keys validated successfully!');
    });

    testWidgets('🎯 Betting System Validation', (WidgetTester tester) async {
      app.main();
      await tester.pumpAndSettle(const Duration(seconds: 2));
      
      await _validateBettingControls(tester);
    });

    testWidgets('🔄 Game State Management Validation', (WidgetTester tester) async {
      app.main();
      await tester.pumpAndSettle(const Duration(seconds: 2));
      
      await _validateGameStateTransitions(tester);
    });
  });
}

/// Phase 1: Navigation Keys Validation
/// Validates: slotsGameCard, rouletteGameCard, blackjackGameCard, demoModeCard
Future<void> _validateNavigationKeys(WidgetTester tester) async {
  print('🔍 Phase 1: Validating navigation keys...');
  
  // Validate slots game navigation
  final slotsCard = find.byKey(const Key('slotsGameCard'));
  expect(slotsCard, findsOneWidget, reason: 'Slots game card must be present');
  await tester.tap(slotsCard);
  await tester.pumpAndSettle();
  print('  ✅ slotsGameCard - Navigation successful');
  
  // Return to home - assuming back navigation
  await tester.pageBack();
  await tester.pumpAndSettle();
  
  // Validate roulette game navigation
  final rouletteCard = find.byKey(const Key('rouletteGameCard'));
  expect(rouletteCard, findsOneWidget, reason: 'Roulette game card must be present');
  await tester.tap(rouletteCard);
  await tester.pumpAndSettle();
  print('  ✅ rouletteGameCard - Navigation successful');
  
  await tester.pageBack();
  await tester.pumpAndSettle();
  
  // Validate blackjack game navigation
  final blackjackCard = find.byKey(const Key('blackjackGameCard'));
  expect(blackjackCard, findsOneWidget, reason: 'Blackjack game card must be present');
  await tester.tap(blackjackCard);
  await tester.pumpAndSettle();
  print('  ✅ blackjackGameCard - Navigation successful');
  
  await tester.pageBack();
  await tester.pumpAndSettle();
  
  // Validate demo mode navigation
  final demoCard = find.byKey(const Key('demoModeCard'));
  expect(demoCard, findsOneWidget, reason: 'Demo mode card must be present');
  await tester.tap(demoCard);
  await tester.pumpAndSettle();
  print('  ✅ demoModeCard - Navigation successful');
  
  await tester.pageBack();
  await tester.pumpAndSettle();
  
  print('✅ Phase 1 Complete: All navigation keys validated');
}

/// Phase 2: Slots Module Validation
/// Validates: spinButton
Future<void> _validateSlotsModule(WidgetTester tester) async {
  print('🔍 Phase 2: Validating slots module...');
  
  // Navigate to slots game
  await tester.tap(find.byKey(const Key('slotsGameCard')));
  await tester.pumpAndSettle();
  
  // Validate spin button presence and functionality
  final spinButton = find.byKey(const Key('spinButton'));
  expect(spinButton, findsOneWidget, reason: 'Spin button must be present in slots game');
  
  // Get initial balance for validation
  final balanceTextFinder = find.textContaining('Balance');
  expect(balanceTextFinder, findsAtLeastNWidget(1), reason: 'Balance display must be visible');
  
  // Execute spin action
  await tester.tap(spinButton);
  await tester.pump(); // Start animation
  await tester.pumpAndSettle(const Duration(seconds: 3)); // Wait for spin completion
  
  print('  ✅ spinButton - Spin executed successfully');
  
  // Validate that game state changed (balance may have changed)
  expect(balanceTextFinder, findsAtLeastNWidget(1), reason: 'Balance should still be displayed after spin');
  
  await tester.pageBack();
  await tester.pumpAndSettle();
  
  print('✅ Phase 2 Complete: Slots module validated');
}

/// Phase 3: Roulette Module Validation  
/// Validates: redBet, blackBet, spinRouletteButton
Future<void> _validateRouletteModule(WidgetTester tester) async {
  print('🔍 Phase 3: Validating roulette module...');
  
  // Navigate to roulette game
  await tester.tap(find.byKey(const Key('rouletteGameCard')));
  await tester.pumpAndSettle();
  
  // Validate betting buttons
  final redBet = find.byKey(const Key('redBet'));
  final blackBet = find.byKey(const Key('blackBet'));
  final spinRouletteButton = find.byKey(const Key('spinRouletteButton'));
  
  expect(redBet, findsOneWidget, reason: 'Red bet button must be present');
  expect(blackBet, findsOneWidget, reason: 'Black bet button must be present');  
  expect(spinRouletteButton, findsOneWidget, reason: 'Roulette spin button must be present');
  
  // Test red bet placement
  await tester.tap(redBet);
  await tester.pumpAndSettle();
  print('  ✅ redBet - Bet placed on red');
  
  // Execute roulette spin
  await tester.tap(spinRouletteButton);
  await tester.pump();
  await tester.pumpAndSettle(const Duration(seconds: 4)); // Wait for roulette animation
  print('  ✅ spinRouletteButton - Roulette spin executed');
  
  // Test black bet placement  
  await tester.tap(blackBet);
  await tester.pumpAndSettle();
  print('  ✅ blackBet - Bet placed on black');
  
  // Execute another spin to validate black bet
  await tester.tap(spinRouletteButton);
  await tester.pump();
  await tester.pumpAndSettle(const Duration(seconds: 4));
  
  await tester.pageBack();
  await tester.pumpAndSettle();
  
  print('✅ Phase 3 Complete: Roulette module validated');
}

/// Phase 4: Blackjack Module Validation
/// Validates: dealButton, hitButton, standButton, newGameButton  
Future<void> _validateBlackjackModule(WidgetTester tester) async {
  print('🔍 Phase 4: Validating blackjack module...');
  
  // Navigate to blackjack game
  await tester.tap(find.byKey(const Key('blackjackGameCard')));
  await tester.pumpAndSettle();
  
  // Validate deal button and start game
  final dealButton = find.byKey(const Key('dealButton'));
  expect(dealButton, findsOneWidget, reason: 'Deal button must be present');
  
  await tester.tap(dealButton);
  await tester.pumpAndSettle(const Duration(seconds: 2));
  print('  ✅ dealButton - Cards dealt successfully');
  
  // Validate game action buttons appear after deal
  final hitButton = find.byKey(const Key('hitButton'));
  final standButton = find.byKey(const Key('standButton'));
  
  expect(hitButton, findsOneWidget, reason: 'Hit button must be present after deal');
  expect(standButton, findsOneWidget, reason: 'Stand button must be present after deal');
  
  // Test hit action
  await tester.tap(hitButton);
  await tester.pumpAndSettle(const Duration(seconds: 1));
  print('  ✅ hitButton - Hit action executed');
  
  // Test stand action (this should trigger dealer play)
  await tester.tap(standButton);
  await tester.pumpAndSettle(const Duration(seconds: 3)); // Wait for dealer sequence
  print('  ✅ standButton - Stand action and dealer play executed');
  
  // Validate new game button appears after game completion
  final newGameButton = find.byKey(const Key('newGameButton'));
  expect(newGameButton, findsOneWidget, reason: 'New game button must appear after game completion');
  
  await tester.tap(newGameButton);
  await tester.pumpAndSettle();
  print('  ✅ newGameButton - New game started successfully');
  
  await tester.pageBack();
  await tester.pumpAndSettle();
  
  print('✅ Phase 4 Complete: Blackjack module validated');
}

