/// Game State Transition Validation
/// Tests transitions between different game states
Future<void> _validateGameStateTransitions(WidgetTester tester) async {
  print('🔍 Validating game state transitions...');
  
  // Test rapid navigation between games to validate state management
  final gameCards = [
    const Key('slotsGameCard'),
    const Key('rouletteGameCard'), 
    const Key('blackjackGameCard'),
    const Key('demoModeCard')
  ];
  
  for (final gameKey in gameCards) {
    await tester.tap(find.byKey(gameKey));
    await tester.pumpAndSettle(const Duration(milliseconds: 500));
    await tester.pageBack();
    await tester.pumpAndSettle(const Duration(milliseconds: 500));
    print('  ✅ State transition validated for ${gameKey.value}');
  }
  
  print('✅ Game state transitions validation complete');
}

